// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "Test", "TST"); }
    function testFuzz_property(uint256 initialSupply, uint256 burnAmount) public {
        vm.assume(initialSupply > 0);
        vm.assume(burnAmount <= initialSupply);
        c = new ERCDDAToken(initialSupply, "Test", "TST");
        uint256 totalSupplyBefore = c.totalSupply();
        vm.prank(address(this));
        c.burn(burnAmount);
        uint256 totalSupplyAfter = c.totalSupply();
        assertTrue(totalSupplyAfter == totalSupplyBefore - burnAmount);
    }
}
